const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');

const PROTO_PATH = './service.proto';
const packageDefinition = protoLoader.loadSync(PROTO_PATH, {
  keepCase: true,
  longs: String,
  enums: String,
  defaults: true,
  oneofs: true
});

const serviceProto = grpc.loadPackageDefinition(packageDefinition).internal;

// Lambda handler that proxies requests to internal gRPC service
exports.handler = async (event) => {
  const endpoint = process.env.GRPC_ENDPOINT || 'internal-service.local:50051';

  const client = new serviceProto.DataService(
    endpoint,
    grpc.credentials.createInsecure()
  );

  // Extract caller metadata from event headers
  const callerRole = event.headers?.['x-caller-role'] || 'anonymous';
  const callerTenant = event.headers?.['x-tenant-id'] || 'default';
  const traceId = event.headers?.['x-amzn-trace-id'] || '';

  // Build gRPC metadata from incoming request headers
  const metadata = new grpc.Metadata();
  metadata.set('x-caller-role', callerRole);
  metadata.set('x-tenant-id', callerTenant);
  metadata.set('x-trace-id', traceId);

  // VULNERABILITY: User-controlled headers are passed directly as gRPC metadata
  // An attacker can inject arbitrary metadata keys that the downstream service
  // trusts for authorization decisions
  if (event.headers) {
    const propagateHeaders = Object.keys(event.headers).filter(
      h => h.startsWith('x-internal-') || h.startsWith('x-auth-')
    );
    for (const header of propagateHeaders) {
      metadata.set(header, event.headers[header]);
    }
  }

  // The downstream gRPC service checks 'x-internal-admin' metadata
  // to grant admin access - attacker can set this via HTTP header
  const request = {
    query: event.body?.query || '',
    limit: parseInt(event.body?.limit) || 100
  };

  return new Promise((resolve, reject) => {
    client.fetchData(request, metadata, (error, response) => {
      if (error) {
        resolve({
          statusCode: 500,
          body: JSON.stringify({ error: error.message })
        });
      } else {
        resolve({
          statusCode: 200,
          body: JSON.stringify(response)
        });
      }
    });
  });
};

// Health check endpoint
exports.health = async () => {
  return {
    statusCode: 200,
    body: JSON.stringify({ status: 'ok', version: '2.4.1' })
  };
};

// Internal metrics - not exposed via API Gateway
exports.metrics = async () => {
  return {
    statusCode: 200,
    body: JSON.stringify({
      connections: grpc.getClientChannel?.()?.getConnectivityState?.() || 'unknown',
      uptime: process.uptime()
    })
  };
};
